function demoMain(idx,label){
  function fails(s){return s.indexOf("bad")>=0&&s.length>5;}
  var inputs=["xxbadxx","bad","zzbadyy","xbad","qqbadqq"]; var inp=inputs[idx%inputs.length];
  var cur=inp; var changed=true;
  while(changed){changed=false;for(var i=0;i<cur.length;i++){var t=cur.slice(0,i)+cur.slice(i+1);if(fails(t)){cur=t;changed=true;break;}}}
  return "["+label+"] minimized failing input '"+inp+"' -> '"+cur+"' ("+cur.length+" chars)";
}

